// Shared helpers for SDX PLAYS Pages Functions.
// Files in folders starting with "_" are not turned into routes.

const IST_OFFSET_MS = 5.5 * 60 * 60 * 1000; // Asia/Kolkata (UTC+05:30, no DST)

/** YYYY-MM-DD in India time for a given UTC timestamp (ms). */
export function istDay(ts = Date.now()) {
  return new Date(ts + IST_OFFSET_MS).toISOString().slice(0, 10);
}

/** YYYY-MM-DD for `n` days before today (India time). */
export function istDayOffset(n, now = Date.now()) {
  return istDay(now - n * 86400000);
}

// Cloudflare Pages does not apply docs/_headers to responses generated by Functions,
// so the same protections are set here. Keep in sync with docs/_headers.
export const SECURITY_HEADERS = {
  "Content-Security-Policy": "default-src 'none'; script-src 'self'; style-src 'self' https://fonts.googleapis.com; font-src https://fonts.gstatic.com; img-src 'self' data:; manifest-src 'self'; connect-src 'self'; base-uri 'self'; form-action 'none'; frame-ancestors 'none'; object-src 'none'; upgrade-insecure-requests",
  "Strict-Transport-Security": "max-age=31536000",
  "X-Content-Type-Options": "nosniff",
  "X-Frame-Options": "DENY",
  "Referrer-Policy": "no-referrer",
  "Cross-Origin-Opener-Policy": "same-origin",
  "Cross-Origin-Resource-Policy": "same-origin",
  "X-Robots-Tag": "noindex, nofollow",
  "Cache-Control": "no-store",
};

export function json(data, status = 200, extra = {}) {
  return new Response(JSON.stringify(data), {
    status,
    headers: { ...SECURITY_HEADERS, "Content-Type": "application/json; charset=utf-8", ...extra },
  });
}

export function empty(status = 204) {
  return new Response(null, {
    status,
    headers: SECURITY_HEADERS,
  });
}

/** Hex HMAC-SHA256(secret, message). */
export async function hmacHex(secret, message) {
  const key = await crypto.subtle.importKey(
    "raw", new TextEncoder().encode(secret),
    { name: "HMAC", hash: "SHA-256" }, false, ["sign"]
  );
  const sig = await crypto.subtle.sign("HMAC", key, new TextEncoder().encode(message));
  return [...new Uint8Array(sig)].map((b) => b.toString(16).padStart(2, "0")).join("");
}

export function deviceFromUA(ua = "") {
  if (/iPad|Tablet|PlayBook|Silk|(Android(?!.*Mobile))/i.test(ua)) return "tablet";
  if (/Mobi|iPhone|iPod|Android|Windows Phone/i.test(ua)) return "mobile";
  return "desktop";
}

// Crawlers, uptime checkers, headless browsers and scripts are not counted.
// (Tracking only runs from page JavaScript, so most link-preview bots never reach it anyway;
//  in-app browsers such as WhatsApp/Instagram are real visitors and are NOT filtered.)
export const BOT_UA = /bot\b|bot\/|crawl|spider|slurp|headless|lighthouse|pagespeed|facebookexternalhit|curl\/|wget|python-|httpclient|java\/|go-http|okhttp|node-fetch|axios|uptime|phantomjs|selenium|puppeteer|playwright/i;
